// Compute target weekend dates (next Sat + Sun from today)
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Sun, 4=Thu, 6=Sat

// From Thursday, next Saturday is +2 days
const daysToSat = (6 - dayOfWeek + 7) % 7 || 7;
const sat = new Date(now);
sat.setDate(now.getDate() + daysToSat);
const sun = new Date(sat);
sun.setDate(sat.getDate() + 1);
const fri = new Date(sat);
fri.setDate(sat.getDate() - 1);

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    friday: fmt(fri),
    saturday: fmt(sat),
    sunday: fmt(sun),
    satLabel: sat.toLocaleDateString('en-US', { month: 'long', day: 'numeric' }),
    sunLabel: sun.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }),
    friLabel: fri.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })
  }
}];

// Normalize, deduplicate, and curate the five weekend sources.
// One deterministic, versioned scorecard decides selected / needs_review / withheld.
const crypto = require('crypto');
const RULE_VERSION = 'bozeman-v1';
const SELECT_MIN = 7;
const REVIEW_MIN = 5;
const MAX_SELECTED_PER_RUN = 40;
const dates = $('Compute Weekend Dates').first().json;
const targetDates = new Set([dates.friday, dates.saturday, dates.sunday]);
const runKey = String($execution.id);
const inputs = $input.all();
const body = (index) => inputs[index]?.json?.data || inputs[index]?.json?.body || inputs[index]?.json || '';

const clean = (value) => String(value || '').replace(/\\n/g, ' ').replace(/\\,/g, ',').replace(/\s+/g, ' ').trim();
const normalized = (value) => clean(value).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const safeUrl = (value) => { try { const url = new URL(String(value || '')); return /^https?:$/.test(url.protocol) ? url.href : null; } catch { return null; } };
const isoDate = (date) => date && !Number.isNaN(date.getTime()) ? date.toISOString().slice(0, 10) : '';
const parseIcalDate = (value) => {
  if (!value) return null;
  const text = value.replace(/Z$/, '');
  if (/^[0-9]{8}$/.test(text)) return new Date(text.slice(0,4)+'-'+text.slice(4,6)+'-'+text.slice(6,8)+'T00:00:00');
  if (/^[0-9]{8}T[0-9]{6}$/.test(text)) return new Date(text.slice(0,4)+'-'+text.slice(4,6)+'-'+text.slice(6,8)+'T'+text.slice(9,11)+':'+text.slice(11,13)+':'+text.slice(13,15));
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};
const targetWeekend = (date) => {
  if (!date || !targetDates.has(isoDate(date))) return false;
  return isoDate(date) !== dates.friday || date.getHours() >= 17;
};

function parseIcal(text) {
  if (typeof text !== 'string') return [];
  return text.split('BEGIN:VEVENT').slice(1).flatMap((block) => {
    const get = (key) => block.match(new RegExp(key + '[^:]*:([^\\r\\n]+)'))?.[1]?.trim() || '';
    const title = clean(get('SUMMARY'));
    const start = parseIcalDate(get('DTSTART'));
    if (!title || !targetWeekend(start)) return [];
    const lower = title.toLowerCase();
    const both = ['score', 'business plan', 'quickbooks', 'marketing workshop', 'entrepreneur', 'small business workshop'].some((term) => lower.includes(term));
    return [{
      title, start, end: parseIcalDate(get('DTEND')), url: safeUrl(get('URL')),
      location: clean(get('LOCATION')) || 'Bozeman, MT', description: clean(get('DESCRIPTION')),
      track: both ? 'both' : 'family', source: 'BoZone',
    }];
  });
}

function parseEventbrite(html) {
  if (typeof html !== 'string') return [];
  const marker = '__SERVER_DATA__ = {';
  const at = html.indexOf(marker);
  if (at < 0) return [];
  const start = at + marker.length - 1;
  let depth = 0, end = start;
  for (let i = start; i < html.length; i++) {
    if (html[i] === '{') depth++;
    else if (html[i] === '}' && --depth === 0) { end = i; break; }
  }
  let data;
  try { data = JSON.parse(html.slice(start, end + 1)); } catch { return []; }
  const relevant = ['real estate','invest','wealth','property','home','remodel','contractor','network','business','entrepreneur','construction','build','renovation','design','trade','industry','professional','workshop','seminar','training','score','chamber','bni','prospera','swmbia','realtor','agent','marketing','sales','leadership','management'];
  const noise = ['concert','live music','dj ','band','scavenger hunt','comedy','trivia','karaoke','dance lesson','yoga','meditation','brewery','distillery','winery','magic show','escape room'];
  return (data?.search_data?.events?.results || []).flatMap((event) => {
    const title = clean(event.name);
    const lower = title.toLowerCase();
    const startAt = new Date(String(event.start_date || '') + 'T' + String(event.start_time || '00:00'));
    if (!title || !targetWeekend(startAt) || noise.some((term) => lower.includes(term)) || !relevant.some((term) => lower.includes(term))) return [];
    const address = clean(event.primary_venue?.address?.localized_address_display);
    if (/(Helena|Missoula|Billings|Butte), MT/i.test(address) && !/Bozeman/i.test(title)) return [];
    const endAt = event.end_date ? new Date(String(event.end_date) + 'T' + String(event.end_time || '23:59')) : null;
    return [{
      title, start: startAt, end: endAt && !Number.isNaN(endAt.getTime()) ? endAt : null,
      url: safeUrl(event.url), location: clean([event.primary_venue?.name, address].filter(Boolean).join(' | ')) || 'Bozeman, MT',
      description: clean(event.summary), track: 'business', source: 'Eventbrite',
    }];
  });
}

const familyTerms = ['market','farmers','workshop','exhibit','author','storytime','kids','family','free','theater','theatre','art','museum','library','park','trail','hike','ski','festival','fair','expo','show','film','movie','science','nature','garden','community','fundraiser','charity','lecture','reading','book'];
const barTerms = ['bar','brewery','brewpub','meadery','taproom','pub','distillery','saloon','tavern','lounge','nightclub','winery'];
const adultTerms = ['21+','18+','adults only','explicit'];

function curate(event) {
  const text = normalized(event.title + ' ' + event.description);
  const location = normalized(event.location);
  const components = { relevance: 0, quality: 0, timing: 0, sourceConfidence: 0, penalties: 0 };
  const reasons = [];
  if (event.track === 'both') { components.relevance = 4; reasons.push('useful for both family and business plans'); }
  else if (event.track === 'business') { components.relevance = 3; reasons.push('matches remodeling, referral, or business interests'); }
  else if (familyTerms.some((term) => text.includes(term))) { components.relevance = 3; reasons.push('clear family or community fit'); }
  else { components.relevance = 2; reasons.push('daytime local event with broad family potential'); }
  components.quality = (event.title ? 1 : 0) + (event.location !== 'Bozeman, MT' ? 1 : 0) + (event.url ? 1 : 0) + (event.description ? 1 : 0);
  if (components.quality >= 3) reasons.push('complete event details');
  components.timing = targetWeekend(event.start) ? 2 : 0;
  if (event.start.getHours() || event.start.getMinutes()) components.timing += 1;
  components.sourceConfidence = event.source === 'BoZone' ? 2 : 1;
  if (event.track === 'family' && event.start.getHours() >= 17 && barTerms.some((term) => location.includes(term))) {
    components.penalties -= 5; reasons.push('late event at an alcohol-focused venue');
  }
  if (adultTerms.some((term) => text.includes(term))) { components.penalties -= 6; reasons.push('adult-only language'); }
  if (/online|webinar|virtual/.test(location + ' ' + text)) { components.penalties -= 2; reasons.push('not an in-person Bozeman event'); }
  const score = Object.values(components).reduce((sum, value) => sum + value, 0);
  const decision = score >= SELECT_MIN ? 'selected' : score >= REVIEW_MIN ? 'needs_review' : 'withheld';
  return { ruleVersion: RULE_VERSION, decision, score, components, reasons };
}

const raw = [
  ...parseIcal(body(0)), ...parseIcal(body(1)), ...parseIcal(body(2)),
  ...parseEventbrite(body(3)), ...parseEventbrite(body(4)),
];
const unique = new Map();
for (const event of raw) {
  const looseKey = normalized(event.title) + '|' + isoDate(event.start) + '|' + normalized(event.location).slice(0, 50);
  if (!unique.has(looseKey)) unique.set(looseKey, event);
}
const candidates = [...unique.values()].map((event) => {
  const fingerprintInput = normalized(event.title) + '|' + event.start.toISOString() + '|' + normalized(event.location);
  return {
    fingerprint: crypto.createHash('sha256').update(fingerprintInput).digest('hex'),
    title: event.title.slice(0, 256), startAt: event.start.toISOString(), endAt: event.end?.toISOString() || null,
    location: event.location.slice(0, 500), description: event.description.slice(0, 2000) || null,
    url: event.url, source: event.source, track: event.track, curation: curate(event), runKey,
  };
});
candidates.sort((a, b) => b.curation.score - a.curation.score || a.startAt.localeCompare(b.startAt));
let selected = 0;
for (const event of candidates) {
  if (event.curation.decision !== 'selected') continue;
  selected++;
  if (selected > MAX_SELECTED_PER_RUN) {
    event.curation.decision = 'needs_review';
    event.curation.reasons.push('held by the 40-card per-run limit');
  }
}
return candidates.map((json) => ({ json }));

const events = $input.all().map((item) => item.json);
const count = (decision) => events.filter((event) => event.curation.decision === decision).length;
return [{ json: { fullMessage: '**Weekend event curation**\n' + events.length + ' candidates: **' + count('selected') + '** selected, **' + count('needs_review') + '** need review, **' + count('withheld') + '** withheld.\nCards below include the reasons each event made the cut.' } }];

