WITH updated AS (
 UPDATE hwc.event_deliveries SET state=CASE WHEN $2 ~ '^[1-9][0-9]{0,19}$' THEN 'delivered' ELSE 'uncertain' END, discord_message_id=NULLIF($2,''), completed_at=now() WHERE fingerprint=$1 AND state='reserved' RETURNING state
)
UPDATE hwc.event_cases SET state=(SELECT state FROM updated), updated_at=now() WHERE fingerprint=$1 RETURNING state;

WITH reserved AS (
 INSERT INTO hwc.event_deliveries (fingerprint, reservation_key, state) VALUES ($1, $2, 'reserved')
 ON CONFLICT (fingerprint) DO NOTHING RETURNING fingerprint
)
UPDATE hwc.event_cases SET state='reserved', updated_at=now() WHERE fingerprint IN (SELECT fingerprint FROM reserved) RETURNING $3::jsonb AS card;
